class User {
  + username : string
  + password : string
}

class Player extends User {
  + lives : int
}

class Admin extends User {
}

class Game {
  + name : string
  + minSpeed : float
  + speedIncreaseFactor : float
  + maxPaddleLength : float
  + minPaddleLength : float
}

class HallOfFame {
}

class Block {
  + color : string
  + points : int
}

class Level {
  + levelNumber : int
  + isRandom : boolean
}

class Cell {
  + gridX : int
  + gridY : int
}

class GameSession {
  + currentScore : int
  + currentLives : int
}

class ScoreEntry {
  + score : int
}

User "1" -- "0..*" Game : manages
User "1..*" Game : plays
Admin "1" -- "0..1" Game : is_admin_of
Player "1" -- "0..*" Game : plays
Game "1" *-- "1" HallOfFame
Game "1" *-- "*" Level
Game "1" *-- "*" Block
Game "1" *-- "0..1" GameSession
HallOfFame "1" -- "*" ScoreEntry
ScoreEntry "1" -- "1" Player
Level "1" *-- "*" Cell
Cell "0..1" -- "0..1" Block

@enduml

